Script.Expression:
const result = $vars.extractCurrentDocument.output ?? {};

if (result.out_Success !== true) {
  throw new Error(
    result.out_ErrorMessage ||
    result.out_ErrorCode ||
    "Document extraction failed."
  );
}

if (
  typeof result.out_ExtractedDocumentJson !== "string" ||
  result.out_ExtractedDocumentJson.trim() === ""
) {
  throw new Error("Document extraction returned no JSON.");
}

let extraction;

try {
  extraction = JSON.parse(result.out_ExtractedDocumentJson);
} catch (error) {
  throw new Error(
    `Invalid extraction JSON for ${$vars.extractDocuments.currentItem}: ${error.message}`
  );
}

return {
  documentPath: $vars.extractDocuments.currentItem,
  extraction
};

const input = $vars.start.output ?? {};

const invoiceRecordId = String($vars.start.output.invoiceRecordId ?? "").trim();
const correlationId = String($vars.start.output.correlationId ?? "").trim();
const contractProfileId = String($vars.start.output.contractProfileId ?? "").trim();

const sourceDocumentIds = Array.isArray($vars.start.output.sourceDocumentIds)
  ? [...new Set(
      $vars.start.output.sourceDocumentIds
        .map(value => String(value ?? "").trim())
        .filter(Boolean)
    )]
  : [];

const missing = [];

if (!invoiceRecordId) missing.push("invoiceRecordId");
if (!correlationId) missing.push("correlationId");
if (!contractProfileId) missing.push("contractProfileId");
if (sourceDocumentIds.length === 0) missing.push("sourceDocumentIds");

if (missing.length > 0) {
  throw new Error(
    `Invalid submission. Missing required input: ${missing.join(", ")}`
  );
}

return {
  invoiceRecordId,
  correlationId,
  contractProfileId,
  sourceDocumentIds,

  // Approved demo identifiers used by ProjectCostLookupApi.
  accountId: "account-lakeshore-regional-health-system",
  projectId: "project-west-pavilion-renovation",

  precedencePolicy: {
    mode: "topic-specific",
    effectiveOnOrBeforeInvoiceDate: true
  }
};

const context = $vars.validateSubmission.output;
const packets = Array.isArray($vars.extractDocuments.output)
  ? $vars.extractDocuments.output
  : [];

const key = value =>
  String(value ?? "").toLowerCase().replace(/[^a-z0-9]/g, "");

const instances = (extraction, groupName) => {
  const group = (extraction?.fieldGroups ?? []).find(
    item => key(item?.name) === key(groupName)
  );
  return Array.isArray(group?.instances) ? group.instances : [];
};

const field = (instance, fieldName) =>
  (instance?.fields ?? []).find(item => key(item?.name) === key(fieldName));

const value = (instance, fieldName, fallback = "") => {
  const result = field(instance, fieldName)?.value;
  return result === null || result === undefined || result === ""
    ? fallback
    : result;
};

const money = input => {
  const parsed = Number(
    String(input ?? "").replace(/,/g, "").replace(/[^\d.+-]/g, "")
  );
  return Number.isFinite(parsed) ? parsed : 0;
};

const documents = [];
const supportingInvoices = [];
const receipts = [];
const canonicalCharges = [];
let invoice = null;
let supplier = { name: "" };
let register = null;

for (const packet of packets) {
  const collected = packet?.collectExtractedDocument?.output ?? packet ?? {};
  const extraction = collected?.extraction ?? {};
  const documentPath = String(
    collected?.documentPath ?? extraction?.sourceDocumentPath ?? ""
  );
  const classification = instances(extraction, "Document Classification")[0];
  const documentType = String(value(classification, "Document Type", "Unknown"));

  documents.push({
    documentId: documentPath,
    bucketPath: documentPath,
    displayName: documentPath.split("/").pop() || documentPath,
    documentType,
    checksum: ""
  });

  if (documentType === "Primary Invoice" || documentType === "Supporting Invoice") {
    const header = instances(extraction, "Invoice Header")[0];
    const totalText = value(header, "Invoice Total", "");
    const headerData = {
      sourceDocumentId: documentPath,
      number: String(value(header, "Invoice Number", "")),
      date: String(value(header, "Invoice Date", "")).slice(0, 10),
      supplierName: String(value(header, "Invoice Supplier Name", "")),
      customerName: String(value(header, "Invoice Customer Name", "")),
      projectName: String(value(header, "Invoice Project Name", "")),
      total: money(totalText),
      currency: (String(totalText).match(/\b[A-Z]{3}\b/) ?? ["USD"])[0]
    };

    if (documentType === "Primary Invoice") {
      invoice = headerData;
      supplier = { name: headerData.supplierName };

      for (const [index, line] of instances(extraction, "Invoice Line Items").entries()) {
        const lineId = String(value(line, "Invoice Line Identifier", String(index + 1)));
        canonicalCharges.push({
          chargeId: `${documentPath}#${lineId}`,
          externalRecordId: `${documentPath}#${lineId}`,
          sourceDocumentId: documentPath,
          sourceDocumentType: documentType,
          description: String(value(line, "Invoice Line Description", `Invoice line ${lineId}`)),
          category: String(value(line, "Invoice Line Category", "unclassified")),
          quantity: money(value(line, "Invoice Line Quantity", "0")),
          unit: String(value(line, "Invoice Line Unit", "")),
          unitRate: money(value(line, "Invoice Line Unit Rate", "0")),
          submittedAmount: money(value(line, "Invoice Line Amount", "0")),
          serviceDate: String(value(line, "Invoice Line Service Date", "")).slice(0, 10),
          reference: String(value(line, "Invoice Line Reference", "")),
          ixpConfidence: Number(line?.confidence ?? 0),
          evidenceTypes: [],
          evidenceDocumentIds: []
        });
      }
    } else {
      supportingInvoices.push(headerData);
    }
  }

  if (documentType === "Receipt") {
    const header = instances(extraction, "Receipt Header")[0];
    receipts.push({
      sourceDocumentId: documentPath,
      receiptNumber: String(value(header, "Receipt Number", "")),
      receiptDate: String(value(header, "Receipt Date", "")).slice(0, 10),
      vendorName: String(value(header, "Receipt Vendor Name", "")),
      total: money(value(header, "Receipt Total", "0"))
    });
  }

  if (documentType === "Cost Register") {
    const header = instances(extraction, "Cost Register Header")[0];
    register = {
      sourceDocumentId: documentPath,
      identifier: String(value(header, "Register Identifier", "")),
      invoiceNumber: String(value(header, "Register Invoice Number", "")),
      total: money(value(header, "Register Total", "0")),
      lines: []
    };
  }
}

invoice ??= {
  sourceDocumentId: "",
  number: "",
  date: "",
  supplierName: "",
  total: 0,
  currency: "USD"
};

register ??= { total: invoice.total, lines: [] };

const missingRequiredFields = [];
if (!supplier.name.trim()) missingRequiredFields.push("Supplier Name");
if (!invoice.number.trim()) missingRequiredFields.push("Invoice Number");
if (!invoice.date.trim()) missingRequiredFields.push("Invoice Date");
if (!(Number(invoice.total) > 0)) missingRequiredFields.push("Invoice Total");

return {
  requiresCorrection: missingRequiredFields.length > 0,
  missingRequiredFields,
  invoiceRecordId: context.invoiceRecordId,
  correlationId: context.correlationId,
  contractProfileId: context.contractProfileId,
  accountId: context.accountId,
  projectId: context.projectId,
  invoice,
  supplier,
  register,
  canonicalCharges,
  documents,
  currency: invoice.currency || "USD",
  supportingInvoices,
  receipts
};

const packageData = $vars.normalizePackage.output;
const correction = $vars.correctRequiredFields.output ?? {};

const supplierName = String(
  correction.correctedSupplierName ?? ""
).trim();

const invoiceNumber = String(
  correction.correctedInvoiceNumber ?? ""
).trim();

const invoiceDate = String(
  correction.correctedInvoiceDate ?? ""
).slice(0, 10);

const invoiceTotal = Number(
  correction.correctedInvoiceTotal ?? 0
);

if (!supplierName) {
  throw new Error("Supplier Name is required.");
}

if (!invoiceNumber) {
  throw new Error("Invoice Number is required.");
}

if (!invoiceDate) {
  throw new Error("Invoice Date is required.");
}

if (!Number.isFinite(invoiceTotal) || invoiceTotal <= 0) {
  throw new Error("Invoice Total must be greater than zero.");
}

return {
  ...packageData,

  invoice: {
    ...(packageData.invoice ?? {}),
    supplierName,
    number: invoiceNumber,
    date: invoiceDate,
    total: invoiceTotal
  },

  supplier: {
    ...(packageData.supplier ?? {}),
    name: supplierName
  },

  missingRequiredFields: [],
  requiresCorrection: false,

  requiredFieldCorrection: {
    applied: true,
    notes: String(
      $vars.requiredFieldCorrectionNotes ?? ""
    ).trim()
  }
};

const packageData = $vars.canonicalPackage ?? {};
const reconciliation = $vars.reconciliationResult ?? {};
const analysis = $vars.contractAnalysis ?? {};

const charges = Array.isArray(packageData.canonicalCharges)
  ? packageData.canonicalCharges
  : [];

const rules = Array.isArray(analysis.normalizedRules)
  ? analysis.normalizedRules
  : [];

const proposals = Array.isArray(analysis.proposedFindings)
  ? analysis.proposedFindings
  : [];

const roundMoney = (value) =>
  Math.round((Number(value ?? 0) + Number.EPSILON) * 100) / 100;

const authoritativeFindings = [];
const calculationLines = [];
const validationErrors = [];

for (const proposal of proposals) {
  const charge = charges.find(
    item => String(item.chargeId) === String(proposal.chargeId)
  );

  const rule = rules.find(
    item => String(item.ruleId) === String(proposal.ruleId)
  );

  if (!charge || !rule) {
    validationErrors.push({
      errorType: "INVALID_REFERENCE",
      findingId: String(proposal.findingId ?? ""),
      message: !charge
        ? "Finding references an unknown charge."
        : "Finding references an unknown rule."
    });
    continue;
  }

  const submitted = roundMoney(charge.submittedAmount);
  const quantity = Number(charge.quantity ?? 0);
  const operands = rule.operands ?? {};

  let allowed = submitted;
  let status = "allowed";
  let trace = [];

  switch (String(rule.ruleType ?? "")) {
    case "CategoryExclusion":
      allowed = 0;
      status = "excluded";
      trace = [
        "The charge matched an excluded contract category.",
        "Allowed amount was set to zero."
      ];
      break;

    case "LaborRateLimit": {
      const maximumRate = Number(operands.maxRate ?? 0);
      allowed = Math.min(submitted, roundMoney(quantity * maximumRate));
      status = allowed < submitted ? "rateCapped" : "allowed";
      trace = [
        "Allowed amount = quantity × maximum contract rate.",
        "Allowed amount cannot exceed the submitted amount."
      ];
      break;
    }

    case "OvertimeRule": {
      const overtimeRate =
        operands.explicitRate !== undefined
          ? Number(operands.explicitRate)
          : Number(operands.straightTimeRate ?? 0) *
            Number(operands.multiplier ?? 0);

      allowed = Math.min(submitted, roundMoney(quantity * overtimeRate));
      status = allowed < submitted ? "overtimeCapped" : "allowed";
      trace = [
        "Allowed amount = quantity × permitted overtime rate.",
        "Allowed amount cannot exceed the submitted amount."
      ];
      break;
    }

    case "PercentageCap": {
      const percentage = Number(operands.percentage ?? 0);
      const eligibleBase = Number(operands.eligibleSubmittedBase ?? 0);
      allowed = Math.min(
        submitted,
        roundMoney(eligibleBase * percentage)
      );
      status = allowed < submitted ? "percentageCapped" : "allowed";
      trace = [
        "Contract cap = eligible submitted base × percentage.",
        "Allowed amount cannot exceed the submitted amount."
      ];
      break;
    }

    case "EquipmentUnitCap": {
      const maximumUnitRate = Number(operands.maxUnitRate ?? 0);
      allowed = Math.min(
        submitted,
        roundMoney(quantity * maximumUnitRate)
      );
      status = allowed < submitted ? "unitCapped" : "allowed";
      trace = [
        "Allowed amount = quantity × maximum equipment unit rate.",
        "Allowed amount cannot exceed the submitted amount."
      ];
      break;
    }

    case "EvidenceRequirement": {
      const evidenceMissing =
        String(proposal.evidenceState ?? "").toLowerCase() !== "valid";

      allowed = evidenceMissing ? 0 : submitted;
      status = evidenceMissing ? "pendingEvidence" : "allowed";
      trace = evidenceMissing
        ? ["Required supporting evidence was not validated."]
        : ["Required supporting evidence was validated."];
      break;
    }

    case "InvoiceRegisterTieOut":
    case "SupportingDocumentTieOut":
      allowed = submitted;
      status = "reconciliationRecorded";
      trace = [
        "The reconciliation exception was recorded.",
        "A reconciliation variance does not automatically create a deduction."
      ];
      break;

    default:
      validationErrors.push({
        errorType: "UNSUPPORTED_RULE",
        findingId: String(proposal.findingId ?? ""),
        ruleId: String(rule.ruleId ?? ""),
        ruleType: String(rule.ruleType ?? ""),
        message: "The proposed finding uses an unsupported rule type."
      });
      continue;
  }

  allowed = roundMoney(allowed);
  const adjustment = roundMoney(submitted - allowed);

  authoritativeFindings.push({
    findingId: String(proposal.findingId ?? ""),
    chargeId: String(charge.chargeId ?? ""),
    ruleId: String(rule.ruleId ?? ""),
    ruleType: String(rule.ruleType ?? ""),
    status,
    submittedAmount: submitted,
    allowedAmount: allowed,
    adjustment,
    sourceDocumentId: String(rule.sourceDocumentId ?? ""),
    sourceClause: String(rule.sourceClause ?? ""),
    explanation: String(proposal.explanation ?? "")
  });

  calculationLines.push({
    findingId: String(proposal.findingId ?? ""),
    chargeId: String(charge.chargeId ?? ""),
    ruleId: String(rule.ruleId ?? ""),
    ruleType: String(rule.ruleType ?? ""),
    operands,
    submittedAmount: submitted,
    allowedAmount: allowed,
    adjustment,
    trace
  });
}

/*
 * If several findings apply to one charge, use its largest adjustment.
 * This prevents deducting the same submitted charge more than once.
 */
const adjustmentByCharge = {};

for (const finding of authoritativeFindings) {
  const chargeId = finding.chargeId;
  const existing = Number(adjustmentByCharge[chargeId] ?? 0);

  adjustmentByCharge[chargeId] = Math.max(
    existing,
    Number(finding.adjustment ?? 0)
  );
}

const totalAdjustment = roundMoney(
  Object.values(adjustmentByCharge).reduce(
    (total, amount) => Number(total) + Number(amount ?? 0),

    0
  )
);

const chargeTotal = roundMoney(
  charges.reduce(
    (total, charge) => total + Number(charge.submittedAmount ?? 0),
    0
  )
);

const submittedTotal = roundMoney(
  Number(packageData.invoice?.total ?? chargeTotal)
);

const comparison =
  reconciliation.invoiceRegisterComparison ?? {};

return {
  status: validationErrors.length === 0 ? "valid" : "invalid",
  authoritativeFindings,
  calculationLines,

  financialSnapshot: {
    submittedTotal,
    totalAdjustment,
    proposedPayable: roundMoney(submittedTotal - totalAdjustment),
    currency: String(packageData.currency ?? "USD"),
    version: 1
  },

  reconciliationState: {
    invoiceRegisterStatus: String(
      comparison.status ??
      reconciliation.invoiceRegisterStatus ??
      ""
    ),
    invoiceTotal:
      comparison.invoiceTotal ??
      reconciliation.invoiceTotal ??
      submittedTotal,
    registerTotal:
      comparison.registerTotal ??
      reconciliation.registerTotal ??
      null,
    invoiceRegisterVariance:
      comparison.variance ??
      reconciliation.invoiceRegisterVariance ??
      null,
    supportingDocumentComparisons:
      reconciliation.supportingDocumentComparisons ?? []
  },

  validationErrors,
  preservedFindingIds: [],
  traceVersion: "script-demo-1.0",
  errorType:
    validationErrors.length === 0 ? "" : "VALIDATION_ERROR",
  errorMessage:
    validationErrors.length === 0
      ? ""
      : "One or more proposed findings could not be evaluated."
};

const startData = JSON.parse(JSON.stringify(
  $vars.start.output ?? {}
));

const packageData = JSON.parse(JSON.stringify(
  $vars.canonicalPackage ?? {}
));

const analysis = JSON.parse(JSON.stringify(
  $vars.contractAnalysis ?? {}
));

const evaluation = JSON.parse(JSON.stringify(
  $vars.evaluateFinancialFindings.output ?? {}
));

const reconciliation = JSON.parse(JSON.stringify(
  $vars.reconciliationResult ?? {}
));

const snapshot = evaluation.financialSnapshot ?? {};
const proposals = Array.isArray(analysis.proposedFindings)
  ? analysis.proposedFindings
  : [];

const rawFindings = Array.isArray(evaluation.authoritativeFindings)
  ? evaluation.authoritativeFindings
  : [];

const charges = Array.isArray(packageData.canonicalCharges)
  ? packageData.canonicalCharges
  : [];

const proposalFor = findingId =>
  proposals.find(
    item => String(item.findingId) === String(findingId)
  ) ?? {};

const findings = rawFindings.map(finding => {
  const proposal = proposalFor(finding.findingId);
  const adjustment = Number(finding.adjustment ?? 0);
  const evidenceState = String(
    proposal.evidenceState ?? finding.status ?? ""
  );

  return {
    ...finding,
    severity:
      adjustment > 0
        ? "High"
        : /pending|technical|ambiguous/i.test(finding.status ?? "")
          ? "Medium"
          : "Low",
    category: String(finding.ruleType ?? "Contract"),
    title: `${String(finding.ruleType ?? "Contract")} review`,
    explanation: String(
      proposal.explanation ??
      finding.sourceClause ??
      "Reviewer confirmation is required."
    ),
    financialEffect: adjustment,
    confidence: Number(proposal.confidence ?? 1),
    evidenceState,
    contractDocumentTitle: String(
      finding.sourceDocumentId ?? "Contract source"
    ),
    contractClause: String(finding.sourceClause ?? ""),
    contractExcerptSummary: String(finding.sourceClause ?? ""),
    applicabilityExplanation: String(
      proposal.explanation ??
      "The rule was matched to this invoice charge."
    )
  };
});

const lineItems = charges.map(charge => {
  const chargeFindings = findings.filter(
    finding =>
      String(finding.chargeId) === String(charge.chargeId)
  );

  const adjustment = chargeFindings.reduce(
    (maximum, finding) =>
      Math.max(maximum, Number(finding.adjustment ?? 0)),
    0
  );

  const requiresReview = chargeFindings.some(
    finding =>
      /pending|technical|ambiguous/i.test(
        String(finding.status ?? "")
      )
  );

  return {
    ...charge,
    submittedRate: Number(charge.unitRate ?? 0),
    allowedAmount: Math.max(
      0,
      Number(charge.submittedAmount ?? 0) - adjustment
    ),
    adjustment,
    evaluationStatus:
      requiresReview
        ? "NeedsReview"
        : adjustment > 0
          ? "Adjusted"
          : "Allowed",
    sourceReference: String(charge.sourceDocumentId ?? "")
  };
});

const analysisVersion = Number(snapshot.version ?? 1);

const lineRecords = lineItems.map(charge => ({
  InvoiceRecordId: String(startData.invoiceRecordId ?? ""),
  SourceDocumentId: String(charge.sourceDocumentId ?? ""),
  SourceDocumentType: String(
    charge.sourceDocumentType ?? "invoice"
  ),
  Description: String(
    charge.description ?? "Extracted invoice line"
  ),
  Category: String(charge.category ?? "unclassified"),
  Quantity: Number(charge.quantity ?? 1),
  Unit: String(charge.unit ?? "each"),
  SubmittedRate: Number(charge.submittedRate ?? 0),
  SubmittedAmount: Number(charge.submittedAmount ?? 0),
  IxpConfidence: Number(charge.ixpConfidence ?? 0),
  SourceCoordinatesJson: JSON.stringify(
    charge.sourceCoordinates ?? {}
  ),
  ExternalRecordId: String(
    charge.externalRecordId ?? charge.chargeId ?? ""
  ),
  ExternalMatchStatus: String(
    charge.externalMatchStatus ?? "NotMatched"
  ),
  ExternalAmount: Number(charge.externalAmount ?? 0),
  Variance: Number(charge.variance ?? 0),
  AllowedAmount: Number(charge.allowedAmount ?? 0),
  Adjustment: Number(charge.adjustment ?? 0),
  EvaluationStatus: String(
    charge.evaluationStatus ?? "NeedsReview"
  ),
  AnalysisVersion: analysisVersion
}));

const awaitingEvidence = findings.some(
  finding =>
    finding.status === "pendingEvidence" ||
    /missing/i.test(String(finding.evidenceState ?? ""))
);

const submittedTotal = Number(
  snapshot.submittedTotal ??
  packageData.invoice?.total ??
  0
);

const adjustmentTotal = Number(snapshot.totalAdjustment ?? 0);
const payableTotal = Number(
  snapshot.proposedPayable ??
  submittedTotal - adjustmentTotal
);

const processingStatus = awaitingEvidence
  ? "AwaitingEvidence"
  : "ReviewerPending";

const timestamp = new Date().toISOString();

const activity = [{
  eventTimestamp: timestamp,
  eventName: "Initial analysis completed",
  eventType: "AnalysisVersionCreated",
  summary: awaitingEvidence
    ? "Initial analysis completed; evidence review is required."
    : "Initial analysis completed and is ready for reviewer confirmation."
}];

const mainRecord = {
  ProcessingStatus: processingStatus,
  SupplierName: String(packageData.supplier?.name ?? ""),
  InvoiceNumber: String(packageData.invoice?.number ?? ""),
  InvoiceDate: String(packageData.invoice?.date ?? ""),
  SubmittedTotal: submittedTotal,
  AdjustmentTotal: adjustmentTotal,
  PayableTotal: payableTotal,
  OpenFindingCount: findings.length,
  AwaitingEvidence: awaitingEvidence,
  AnalysisVersion: analysisVersion,
  FindingsJson: JSON.stringify(findings),
  DocumentReferencesJson: JSON.stringify(
    packageData.documents ?? []
  ),
  CorrelationId: String(startData.correlationId ?? ""),
  ContractProfileId: String(startData.contractProfileId ?? ""),
  AccountId: String(packageData.accountId ?? ""),
  ProjectId: String(packageData.projectId ?? "")
};

const activityRecord = {
  InvoiceRecordId: String(startData.invoiceRecordId ?? ""),
  CorrelationId: String(startData.correlationId ?? ""),
  EventTimestamp: timestamp,
  EventName: "Initial analysis completed",
  EventType: "AnalysisVersionCreated",
  EventSource: "InvoiceAssuranceFlow",
  Summary: activity[0].summary,

  // Keep this intentionally small because PayloadJson is limited.
  PayloadJson: JSON.stringify({
    analysisVersion,
    submittedTotal,
    adjustmentTotal,
    payableTotal,
    findingCount: findings.length,
    awaitingEvidence
  })
};

return {
  status: evaluation.status ?? "valid",
  invoiceRecordId: String(startData.invoiceRecordId ?? ""),
  correlationId: String(startData.correlationId ?? ""),
  analysisVersion,
  reviewCycle: 1,
  financialSnapshot: {
    ...snapshot,
    submittedTotal,
    totalAdjustment: adjustmentTotal,
    proposedPayable: payableTotal,
    version: analysisVersion
  },
  invoiceSummary: {
    invoiceNumber: String(packageData.invoice?.number ?? ""),
    invoiceDate: String(packageData.invoice?.date ?? ""),
    supplierName: String(packageData.supplier?.name ?? ""),
    accountName: "Lakeshore Regional Health System",
    projectName: String(
      reconciliation.projectMatch?.projectName ??
      "West Pavilion Renovation"
    ),
    contractProfileId: String(
      startData.contractProfileId ?? ""
    ),
    submittedTotal,
    currentAdjustment: adjustmentTotal,
    currentPayable: payableTotal,
    openFindingCount: findings.length,
    awaitingEvidence
  },
  authoritativeFindings: findings,
  lineItems,
  lineRecords,
  documents: packageData.documents ?? [],
  activity,
  mainRecord,
  activityRecord
};

const result = JSON.parse(JSON.stringify(
  $vars.persistInitialAnalysis.output ?? {}
));

if (result.out_Success !== true) {
  const code = String(
    result.out_ErrorCode ?? "PersistenceError"
  );

  const message = String(
    result.out_ErrorMessage ??
    "Initial persistence failed without an error message."
  );

  throw new Error(
    `Initial persistence failed [${code}]: ${message}`
  );
}

return {
  status: "Unexpected success routing"
};

const previous = JSON.parse(JSON.stringify(
  $vars.buildInitialReviewPackage.output ?? {}
));

const decision = JSON.parse(JSON.stringify(
  $vars.reviewInvoiceAssuranceFindings.output ?? {}
));

const packageData = JSON.parse(JSON.stringify(
  $vars.canonicalPackage ?? {}
));

const reconciliation = JSON.parse(JSON.stringify(
  $vars.reconciliationResult ?? {}
));

const findings = Array.isArray(previous.authoritativeFindings)
  ? previous.authoritativeFindings
  : [];

const uploadedEvidence = Array.isArray(decision.uploadedEvidence)
  ? decision.uploadedEvidence
  : [];

const evidenceWasResolved =
  uploadedEvidence.length > 0 &&
  String(decision.evidenceStatus ?? "").toLowerCase() ===
    "resolved";

const evidenceFindingIds = evidenceWasResolved
  ? findings
      .filter(finding =>
        finding.status === "pendingEvidence" ||
        /missing/i.test(String(finding.evidenceState ?? ""))
      )
      .map(finding => finding.findingId)
  : [];

const affectedChargeIds = findings
  .filter(finding =>
    evidenceFindingIds.includes(finding.findingId)
  )
  .map(finding => finding.chargeId)
  .filter((value, index, values) =>
    Boolean(value) && values.indexOf(value) === index
  );

const canonicalCharges = (
  packageData.canonicalCharges ?? []
).map(charge => {
  const existingEvidence = Array.isArray(charge.evidenceTypes)
    ? charge.evidenceTypes
    : [];

  const evidenceTypes = affectedChargeIds.includes(
    charge.chargeId
  )
    ? [...existingEvidence, "itemized-receipt"].filter(
        (value, index, values) =>
          values.indexOf(value) === index
      )
    : existingEvidence;

  return {
    ...charge,
    evidenceTypes
  };
});

const newDocuments = uploadedEvidence.map(item => ({
  documentId: String(
    item.evidenceId ?? item.bucketPath ?? ""
  ),
  bucketId: Number(item.bucketId ?? 0),
  bucketPath: String(item.bucketPath ?? ""),
  displayName: String(
    item.displayName ?? item.bucketPath ?? "Reviewer evidence"
  ),
  documentType: "supporting-evidence",
  checksum: String(item.checksum ?? "")
}));

const documents = [
  ...(Array.isArray(previous.documents)
    ? previous.documents
    : packageData.documents ?? []),
  ...newDocuments
];

const comparison = {
  ...(reconciliation.invoiceRegisterComparison ?? {})
};

const correctedRegisterAmount = Number(
  decision.correctedRegisterAmount
);

const correctionReason = String(
  decision.registerCorrectionReason ?? ""
).trim();

const hasRegisterCorrection =
  Number.isFinite(correctedRegisterAmount) &&
  correctedRegisterAmount >= 0 &&
  correctionReason.length > 0;

const invoiceTotal = Number(
  comparison.invoiceTotal ??
  previous.invoiceSummary?.submittedTotal ??
  0
);

const registerVariance = hasRegisterCorrection
  ? invoiceTotal - correctedRegisterAmount
  : Number(comparison.variance ?? 0);

const reconciliationSummary = {
  ...reconciliation,
  invoiceRegisterComparison: {
    ...comparison,
    ...(hasRegisterCorrection
      ? {
          registerTotal: correctedRegisterAmount,
          variance: registerVariance,
          status:
            Math.abs(registerVariance) <= 0.01
              ? "Tied"
              : "Variance",
          correctionReason
        }
      : {})
  }
};

const reconciliationFindingIds = hasRegisterCorrection
  ? findings
      .filter(finding =>
        /reconciliation/i.test(
          String(
            finding.evidenceState ??
            finding.ruleType ??
            finding.category ??
            ""
          )
        )
      )
      .map(finding => finding.findingId)
  : [];

const requestedFindingIds = Array.isArray(
  decision.changedFindingIds
)
  ? decision.changedFindingIds
  : [];

let changedFindingIds = [
  ...requestedFindingIds,
  ...evidenceFindingIds,
  ...reconciliationFindingIds
].filter(
  (value, index, values) =>
    Boolean(value) && values.indexOf(value) === index
);

/*
 * For the demo, if the reviewer submits without identifying a
 * specific changed finding, recheck all existing findings.
 */
if (changedFindingIds.length === 0) {
  changedFindingIds = findings
    .map(finding => finding.findingId)
    .filter(Boolean);
}

return {
  canonicalCharges,
  documents,
  reconciliationSummary,
  changedFindingIds,
  humanOverride: String(decision.reviewerNotes ?? ""),
  reviewerDecision: decision,
  previousSnapshot: previous,
  priorActivity: Array.isArray(previous.activity)
    ? previous.activity
    : [],
  invoiceRecordId: String(
    previous.invoiceRecordId ??
    $vars.start.output.invoiceRecordId ??
    ""
  ),
  correlationId: String(
    previous.correlationId ??
    $vars.start.output.correlationId ??
    ""
  ),
  contractProfileId: String(
    $vars.start.output.contractProfileId ?? ""
  ),
  invoiceDate: String(packageData.invoice?.date ?? ""),
  currency: String(packageData.currency ?? "USD"),
  invoiceSubmittedTotal: Number(
    previous.financialSnapshot?.submittedTotal ??
    packageData.invoice?.total ??
    0
  )
};

const reviewerChanges = JSON.parse(JSON.stringify(
  $vars.applyReviewerChanges.output ?? {}
));

const basePackage = JSON.parse(JSON.stringify(
  $vars.canonicalPackage ?? {}
));

const packageData = {
  ...basePackage,
  canonicalCharges:
    reviewerChanges.canonicalCharges ??
    basePackage.canonicalCharges ??
    [],
  documents:
    reviewerChanges.documents ??
    basePackage.documents ??
    []
};

const reconciliation =
  reviewerChanges.reconciliationSummary ?? {};

const analysis = JSON.parse(JSON.stringify(
  $vars.reanalyzeReviewerChanges.output ?? {}
));

const previousSnapshot =
  reviewerChanges.previousSnapshot ?? {};

const changedFindingIds = Array.isArray(
  reviewerChanges.changedFindingIds
)
  ? reviewerChanges.changedFindingIds
  : [];

const charges = Array.isArray(packageData.canonicalCharges)
  ? packageData.canonicalCharges
  : [];

const rules = Array.isArray(analysis.normalizedRules)
  ? analysis.normalizedRules
  : [];

const allProposals = Array.isArray(analysis.proposedFindings)
  ? analysis.proposedFindings
  : [];

const proposals = changedFindingIds.length > 0
  ? allProposals.filter(proposal =>
      changedFindingIds.includes(proposal.findingId)
    )
  : allProposals;

const roundMoney = (value) =>
  Math.round((Number(value ?? 0) + Number.EPSILON) * 100) / 100;

const authoritativeFindings = [];
const calculationLines = [];
const validationErrors = [];

for (const proposal of proposals) {
  const charge = charges.find(
    item => String(item.chargeId) === String(proposal.chargeId)
  );

  const rule = rules.find(
    item => String(item.ruleId) === String(proposal.ruleId)
  );

  if (!charge || !rule) {
    validationErrors.push({
      errorType: "INVALID_REFERENCE",
      findingId: String(proposal.findingId ?? ""),
      message: !charge
        ? "Finding references an unknown charge."
        : "Finding references an unknown rule."
    });
    continue;
  }

  const submitted = roundMoney(charge.submittedAmount);
  const quantity = Number(charge.quantity ?? 0);
  const operands = rule.operands ?? {};

  let allowed = submitted;
  let status = "allowed";
  let trace = [];

  switch (String(rule.ruleType ?? "")) {
    case "CategoryExclusion":
      allowed = 0;
      status = "excluded";
      trace = [
        "The charge matched an excluded contract category.",
        "Allowed amount was set to zero."
      ];
      break;

    case "LaborRateLimit": {
      const maximumRate = Number(operands.maxRate ?? 0);
      allowed = Math.min(submitted, roundMoney(quantity * maximumRate));
      status = allowed < submitted ? "rateCapped" : "allowed";
      trace = [
        "Allowed amount = quantity × maximum contract rate.",
        "Allowed amount cannot exceed the submitted amount."
      ];
      break;
    }

    case "OvertimeRule": {
      const overtimeRate =
        operands.explicitRate !== undefined
          ? Number(operands.explicitRate)
          : Number(operands.straightTimeRate ?? 0) *
            Number(operands.multiplier ?? 0);

      allowed = Math.min(submitted, roundMoney(quantity * overtimeRate));
      status = allowed < submitted ? "overtimeCapped" : "allowed";
      trace = [
        "Allowed amount = quantity × permitted overtime rate.",
        "Allowed amount cannot exceed the submitted amount."
      ];
      break;
    }

    case "PercentageCap": {
      const percentage = Number(operands.percentage ?? 0);
      const eligibleBase = Number(operands.eligibleSubmittedBase ?? 0);
      allowed = Math.min(
        submitted,
        roundMoney(eligibleBase * percentage)
      );
      status = allowed < submitted ? "percentageCapped" : "allowed";
      trace = [
        "Contract cap = eligible submitted base × percentage.",
        "Allowed amount cannot exceed the submitted amount."
      ];
      break;
    }

    case "EquipmentUnitCap": {
      const maximumUnitRate = Number(operands.maxUnitRate ?? 0);
      allowed = Math.min(
        submitted,
        roundMoney(quantity * maximumUnitRate)
      );
      status = allowed < submitted ? "unitCapped" : "allowed";
      trace = [
        "Allowed amount = quantity × maximum equipment unit rate.",
        "Allowed amount cannot exceed the submitted amount."
      ];
      break;
    }

    case "EvidenceRequirement": {
      const evidenceMissing =
        String(proposal.evidenceState ?? "").toLowerCase() !== "valid";

      allowed = evidenceMissing ? 0 : submitted;
      status = evidenceMissing ? "pendingEvidence" : "allowed";
      trace = evidenceMissing
        ? ["Required supporting evidence was not validated."]
        : ["Required supporting evidence was validated."];
      break;
    }

    case "InvoiceRegisterTieOut":
    case "SupportingDocumentTieOut":
      allowed = submitted;
      status = "reconciliationRecorded";
      trace = [
        "The reconciliation exception was recorded.",
        "A reconciliation variance does not automatically create a deduction."
      ];
      break;

    default:
      validationErrors.push({
        errorType: "UNSUPPORTED_RULE",
        findingId: String(proposal.findingId ?? ""),
        ruleId: String(rule.ruleId ?? ""),
        ruleType: String(rule.ruleType ?? ""),
        message: "The proposed finding uses an unsupported rule type."
      });
      continue;
  }

  allowed = roundMoney(allowed);
  const adjustment = roundMoney(submitted - allowed);

  authoritativeFindings.push({
    findingId: String(proposal.findingId ?? ""),
    chargeId: String(charge.chargeId ?? ""),
    ruleId: String(rule.ruleId ?? ""),
    ruleType: String(rule.ruleType ?? ""),
    status,
    submittedAmount: submitted,
    allowedAmount: allowed,
    adjustment,
    sourceDocumentId: String(rule.sourceDocumentId ?? ""),
    sourceClause: String(rule.sourceClause ?? ""),
    explanation: String(proposal.explanation ?? "")
  });

  calculationLines.push({
    findingId: String(proposal.findingId ?? ""),
    chargeId: String(charge.chargeId ?? ""),
    ruleId: String(rule.ruleId ?? ""),
    ruleType: String(rule.ruleType ?? ""),
    operands,
    submittedAmount: submitted,
    allowedAmount: allowed,
    adjustment,
    trace
  });
}

const previousFindings = Array.isArray(
  previousSnapshot.authoritativeFindings
)
  ? previousSnapshot.authoritativeFindings
  : [];

for (const previousFinding of previousFindings) {
  const wasChanged = changedFindingIds.includes(
    previousFinding.findingId
  );

  const alreadyPresent = authoritativeFindings.some(
    finding =>
      String(finding.findingId) ===
      String(previousFinding.findingId)
  );

  if (!wasChanged && !alreadyPresent) {
    authoritativeFindings.push(previousFinding);
  }
}

const previousCalculationLines = Array.isArray(
  previousSnapshot.calculationLines
)
  ? previousSnapshot.calculationLines
  : [];

for (const previousLine of previousCalculationLines) {
  const wasChanged = changedFindingIds.includes(
    previousLine.findingId
  );

  const alreadyPresent = calculationLines.some(
    line =>
      String(line.findingId) ===
      String(previousLine.findingId)
  );

  if (!wasChanged && !alreadyPresent) {
    calculationLines.push(previousLine);
  }
}
/*
 * If several findings apply to one charge, use its largest adjustment.
 * This prevents deducting the same submitted charge more than once.
 */
const adjustmentByCharge = {};

for (const finding of authoritativeFindings) {
  const chargeId = finding.chargeId;
  const existing = Number(adjustmentByCharge[chargeId] ?? 0);

  adjustmentByCharge[chargeId] = Math.max(
    existing,
    Number(finding.adjustment ?? 0)
  );
}

const totalAdjustment = roundMoney(
  Object.values(adjustmentByCharge).reduce(
    (total, amount) => Number(total) + Number(amount ?? 0),

    0
  )
);

const chargeTotal = roundMoney(
  charges.reduce(
    (total, charge) => total + Number(charge.submittedAmount ?? 0),
    0
  )
);

const submittedTotal = roundMoney(
  Number(packageData.invoice?.total ?? chargeTotal)
);

const comparison =
  reconciliation.invoiceRegisterComparison ?? {};

return {
  status: validationErrors.length === 0 ? "valid" : "invalid",
  authoritativeFindings,
  calculationLines,

  financialSnapshot: {
    submittedTotal,
    totalAdjustment,
    proposedPayable: roundMoney(submittedTotal - totalAdjustment),
    currency: String(packageData.currency ?? "USD"),
    version: Number(
      previousSnapshot.analysisVersion ??
      previousSnapshot.financialSnapshot?.version ??
      1
    ) + 1
  },

  reconciliationState: {
    invoiceRegisterStatus: String(
      comparison.status ??
      reconciliation.invoiceRegisterStatus ??
      ""
    ),
    invoiceTotal:
      comparison.invoiceTotal ??
      reconciliation.invoiceTotal ??
      submittedTotal,
    registerTotal:
      comparison.registerTotal ??
      reconciliation.registerTotal ??
      null,
    invoiceRegisterVariance:
      comparison.variance ??
      reconciliation.invoiceRegisterVariance ??
      null,
    supportingDocumentComparisons:
      reconciliation.supportingDocumentComparisons ?? []
  },

  validationErrors,
  preservedFindingIds: [],
  traceVersion: "script-demo-1.0",
  errorType:
    validationErrors.length === 0 ? "" : "VALIDATION_ERROR",
  errorMessage:
    validationErrors.length === 0
      ? ""
      : "One or more proposed findings could not be evaluated."
};

const changes = JSON.parse(JSON.stringify(
  $vars.applyReviewerChanges.output ?? {}
));

const evaluation = JSON.parse(JSON.stringify(
  $vars.reevaluateFinancialFindings.output ?? {}
));

const analysis = JSON.parse(JSON.stringify(
  $vars.reanalyzeReviewerChanges.output ?? {}
));

const previous = changes.previousSnapshot ?? {};
const snapshot = evaluation.financialSnapshot ?? {};
const reviewerDecision = changes.reviewerDecision ?? {};

const proposals = Array.isArray(analysis.proposedFindings)
  ? analysis.proposedFindings
  : [];

const rules = Array.isArray(analysis.normalizedRules)
  ? analysis.normalizedRules
  : [];

const proposalFor = findingId =>
  proposals.find(
    item => String(item.findingId) === String(findingId)
  ) ?? {};

const ruleFor = ruleId =>
  rules.find(
    item => String(item.ruleId) === String(ruleId)
  ) ?? {};

const rawFindings = Array.isArray(
  evaluation.authoritativeFindings
)
  ? evaluation.authoritativeFindings
  : [];

const findings = rawFindings.map(finding => {
  const proposal = proposalFor(finding.findingId);
  const rule = ruleFor(finding.ruleId);
  const adjustment = Number(finding.adjustment ?? 0);

  return {
    ...finding,
    severity:
      adjustment > 0
        ? "High"
        : /pending|technical|ambiguous/i.test(
            String(finding.status ?? "")
          )
          ? "Medium"
          : "Low",
    category: String(
      finding.ruleType ?? rule.ruleType ?? "Contract"
    ),
    title: `${String(
      finding.ruleType ?? rule.ruleType ?? "Contract"
    )} review`,
    explanation: String(
      proposal.explanation ??
      finding.explanation ??
      finding.sourceClause ??
      "Reviewer confirmation is required."
    ),
    financialEffect: adjustment,
    confidence: Number(rule.confidence ?? 1),
    evidenceState: String(
      proposal.evidenceState ??
      finding.evidenceState ??
      finding.status ??
      ""
    ),
    contractDocumentTitle: String(
      finding.sourceDocumentId ??
      rule.sourceDocumentId ??
      "Contract source"
    ),
    contractClause: String(
      finding.sourceClause ?? rule.sourceClause ?? ""
    ),
    contractExcerptSummary: String(
      finding.sourceClause ?? rule.sourceClause ?? ""
    ),
    applicabilityExplanation: String(
      proposal.explanation ??
      "The contract rule was applied to this charge."
    )
  };
});

const ambiguities = Array.isArray(analysis.ambiguities)
  ? analysis.ambiguities
  : [];

const ambiguityFindings = ambiguities.map(
  (ambiguity, index) => ({
    findingId: String(
      ambiguity.ambiguityId ?? `ambiguity-${index + 1}`
    ),
    chargeId: String(
      ambiguity.affectedChargeIds?.[0] ?? ""
    ),
    ruleId: "contract-ambiguity",
    ruleType: "ContractAmbiguity",
    severity: "Medium",
    category: "Contract ambiguity",
    title: String(
      ambiguity.topic ?? "Contract interpretation required"
    ),
    explanation: String(
      ambiguity.explanation ??
      "The governing contract position could not be resolved."
    ),
    financialEffect: 0,
    adjustment: 0,
    status: "ambiguous",
    confidence: 0,
    evidenceState: "ambiguous",
    contractDocumentTitle: "Contract source",
    contractClause: String(
      ambiguity.citations?.[0]?.sourceClause ?? ""
    ),
    contractExcerptSummary: String(
      ambiguity.citations?.[0]?.sourceClause ?? ""
    ),
    applicabilityExplanation: String(
      ambiguity.explanation ?? ""
    ),
    sourceDocumentId: String(
      ambiguity.citations?.[0]?.sourceDocumentId ?? ""
    )
  })
);

const allFindings = [
  ...findings,
  ...ambiguityFindings
];

const unresolvedFindings = allFindings.filter(
  finding =>
    /pending|technical|ambiguous/i.test(
      String(finding.status ?? "")
    ) ||
    /missing/i.test(String(finding.evidenceState ?? ""))
);

const awaitingEvidence = unresolvedFindings.some(
  finding =>
    finding.status === "pendingEvidence" ||
    /missing/i.test(String(finding.evidenceState ?? ""))
);

const readiness =
  reviewerDecision.reviewReady === true &&
  evaluation.status === "valid" &&
  unresolvedFindings.length === 0;

const analysisVersion = Number(
  snapshot.version ??
  Number(previous.analysisVersion ?? 1) + 1
);

const reviewCycle =
  Number(previous.reviewCycle ?? 1) + 1;

const canonicalCharges = Array.isArray(
  changes.canonicalCharges
)
  ? changes.canonicalCharges
  : [];

const lineItems = canonicalCharges.map(charge => {
  const chargeFindings = allFindings.filter(
    finding =>
      String(finding.chargeId) === String(charge.chargeId)
  );

  const adjustment = chargeFindings.reduce(
    (maximum, finding) =>
      Math.max(maximum, Number(finding.adjustment ?? 0)),
    0
  );

  const requiresReview = chargeFindings.some(
    finding =>
      /pending|technical|ambiguous/i.test(
        String(finding.status ?? "")
      )
  );

  return {
    ...charge,
    submittedRate: Number(charge.unitRate ?? 0),
    allowedAmount: Math.max(
      0,
      Number(charge.submittedAmount ?? 0) - adjustment
    ),
    adjustment,
    evaluationStatus:
      requiresReview
        ? "NeedsReview"
        : adjustment > 0
          ? "Adjusted"
          : "Allowed",
    sourceReference: String(charge.sourceDocumentId ?? "")
  };
});

const lineRecords = lineItems.map(charge => ({
  InvoiceRecordId: String(changes.invoiceRecordId ?? ""),
  SourceDocumentId: String(charge.sourceDocumentId ?? ""),
  SourceDocumentType: String(
    charge.sourceDocumentType ?? "invoice"
  ),
  Description: String(
    charge.description ?? "Extracted invoice line"
  ),
  Category: String(charge.category ?? "unclassified"),
  Quantity: Number(charge.quantity ?? 1),
  Unit: String(charge.unit ?? "each"),
  SubmittedRate: Number(charge.submittedRate ?? 0),
  SubmittedAmount: Number(charge.submittedAmount ?? 0),
  IxpConfidence: Number(charge.ixpConfidence ?? 0),
  SourceCoordinatesJson: JSON.stringify(
    charge.sourceCoordinates ?? {}
  ),
  ExternalRecordId: String(
    charge.externalRecordId ?? charge.chargeId ?? ""
  ),
  ExternalMatchStatus: String(
    charge.externalMatchStatus ?? "NotMatched"
  ),
  ExternalAmount: Number(charge.externalAmount ?? 0),
  Variance: Number(charge.variance ?? 0),
  AllowedAmount: Number(charge.allowedAmount ?? 0),
  Adjustment: Number(charge.adjustment ?? 0),
  EvaluationStatus: String(
    charge.evaluationStatus ?? "NeedsReview"
  ),
  AnalysisVersion: analysisVersion
}));

const submittedTotal = Number(snapshot.submittedTotal ?? 0);
const adjustmentTotal = Number(snapshot.totalAdjustment ?? 0);
const payableTotal = Number(snapshot.proposedPayable ?? 0);

const processingStatus = readiness
  ? "ManagerPending"
  : awaitingEvidence
    ? "AwaitingEvidence"
    : "ReviewerPending";

const timestamp = new Date().toISOString();

const activityEntry = {
  eventTimestamp: timestamp,
  eventName: "Reviewer changes evaluated",
  eventType: "AnalysisVersionCreated",
  summary: readiness
    ? "Reviewer changes resolved; ready for Manager review."
    : "Additional Reviewer work is required."
};

const activity = [
  ...(Array.isArray(changes.priorActivity)
    ? changes.priorActivity
    : []),
  activityEntry
];

const mainRecord = {
  ProcessingStatus: processingStatus,
  SubmittedTotal: submittedTotal,
  AdjustmentTotal: adjustmentTotal,
  PayableTotal: payableTotal,
  OpenFindingCount: allFindings.length,
  AwaitingEvidence: awaitingEvidence,
  AnalysisVersion: analysisVersion,
  FindingsJson: JSON.stringify(allFindings),
  DocumentReferencesJson: JSON.stringify(
    changes.documents ?? []
  )
};

const activityRecord = {
  InvoiceRecordId: String(changes.invoiceRecordId ?? ""),
  CorrelationId: String(changes.correlationId ?? ""),
  EventTimestamp: timestamp,
  EventName: "Reviewer changes evaluated",
  EventType: "AnalysisVersionCreated",
  EventSource: "InvoiceAssuranceFlow",
  Summary: activityEntry.summary,
  PayloadJson: JSON.stringify({
    analysisVersion,
    reviewCycle,
    readiness,
    changedFindingIds: changes.changedFindingIds ?? [],
    findingCount: allFindings.length,
    unresolvedCount: unresolvedFindings.length
  })
};

return {
  ...evaluation,
  invoiceRecordId: String(changes.invoiceRecordId ?? ""),
  correlationId: String(changes.correlationId ?? ""),
  analysisVersion,
  reviewCycle,
  readiness,
  financialSnapshot: {
    ...snapshot,
    submittedTotal,
    totalAdjustment: adjustmentTotal,
    proposedPayable: payableTotal,
    version: analysisVersion
  },
  invoiceSummary: {
    ...(previous.invoiceSummary ?? {}),
    submittedTotal,
    currentAdjustment: adjustmentTotal,
    currentPayable: payableTotal,
    openFindingCount: allFindings.length,
    awaitingEvidence
  },
  authoritativeFindings: allFindings,
  lineItems,
  lineRecords,
  documents: changes.documents ?? [],
  activity,
  mainRecord,
  activityRecord
};

const result = JSON.parse(JSON.stringify(
  $vars.persistReviewerReevaluation.output ?? {}
));

if (result.out_Success !== true) {
  const code = String(
    result.out_ErrorCode ?? "PersistenceError"
  );

  const message = String(
    result.out_ErrorMessage ??
    "Reevaluation persistence failed without an error message."
  );

  throw new Error(
    `Reevaluation persistence failed [${code}]: ${message}`
  );
}

return {
  status: "Unexpected success routing"
};

const packageData = JSON.parse(JSON.stringify(
  $vars.currentReviewPackage ?? {}
));

const decision = JSON.parse(JSON.stringify(
  $vars.managerReview.output ?? {}
));

const managerRationale = String(
  decision.managerRationale ??
  "Manager returned the invoice for additional review."
);

const timestamp = new Date().toISOString();

const activityEntry = {
  eventTimestamp: timestamp,
  eventName: "Returned by Manager",
  eventType: "ManagerReturn",
  summary: managerRationale
};

return {
  managerRationale,

  reviewPackage: {
    ...packageData,

    readiness: false,

    mainRecord: {
      ...(packageData.mainRecord ?? {}),
      ProcessingStatus: "ReviewerPending"
    },

    activity: [
      ...(Array.isArray(packageData.activity)
        ? packageData.activity
        : []),
      activityEntry
    ]
  }
};

const packageData = JSON.parse(JSON.stringify(
  $vars.currentReviewPackage ?? {}
));

const decision = JSON.parse(JSON.stringify(
  $vars.managerReview.output ?? {}
));

const action = String(decision.Action ?? "");

if (action !== "Approve" && action !== "Reject") {
  throw new Error(
    `Invalid final Manager action: ${action || "empty"}`
  );
}

const processingStatus =
  action === "Approve" ? "Approved" : "Rejected";

const snapshot = packageData.financialSnapshot ?? {};

const findings = Array.isArray(
  packageData.authoritativeFindings
)
  ? packageData.authoritativeFindings
  : [];

const unresolvedFindings = findings.filter(
  finding =>
    /pending|technical|ambiguous/i.test(
      String(finding.status ?? "")
    ) ||
    /missing/i.test(String(finding.evidenceState ?? ""))
);

const awaitingEvidence = unresolvedFindings.some(
  finding =>
    finding.status === "pendingEvidence" ||
    /missing/i.test(String(finding.evidenceState ?? ""))
);

const timestamp = new Date().toISOString();

const rationale = String(
  decision.managerRationale ??
  decision.decisionSummary ??
  ""
);

const activitySummary =
  action === "Approve"
    ? "Manager approved the invoice assurance result."
    : `Manager rejected the invoice assurance result${
        rationale ? `: ${rationale}` : "."
      }`;

return {
  invoiceRecordId: String(
    packageData.invoiceRecordId ??
    $vars.start.output.invoiceRecordId ??
    ""
  ),

  correlationId: String(
    packageData.correlationId ??
    $vars.start.output.correlationId ??
    ""
  ),

  action,
  processingStatus,

  lineRecords: Array.isArray(packageData.lineRecords)
    ? packageData.lineRecords
    : [],

  mainRecord: {
    ...(packageData.mainRecord ?? {}),
    ProcessingStatus: processingStatus,
    SubmittedTotal: Number(snapshot.submittedTotal ?? 0),
    AdjustmentTotal: Number(snapshot.totalAdjustment ?? 0),
    PayableTotal: Number(snapshot.proposedPayable ?? 0),
    OpenFindingCount: unresolvedFindings.length,
    AwaitingEvidence: awaitingEvidence,
    AnalysisVersion: Number(
      snapshot.version ??
      packageData.analysisVersion ??
      1
    ),
    FindingsJson: JSON.stringify(findings)
  },

  activityRecord: {
    InvoiceRecordId: String(
      packageData.invoiceRecordId ??
      $vars.start.output.invoiceRecordId ??
      ""
    ),
    CorrelationId: String(
      packageData.correlationId ??
      $vars.start.output.correlationId ??
      ""
    ),
    EventTimestamp: timestamp,
    EventName: "Final disposition recorded",
    EventType: "FinalDisposition",
    EventSource: "InvoiceAssuranceFlow",
    Summary: activitySummary,
    PayloadJson: JSON.stringify({
      action,
      rationale,
      analysisVersion: Number(
        snapshot.version ??
        packageData.analysisVersion ??
        1
      ),
      submittedTotal: Number(snapshot.submittedTotal ?? 0),
      adjustmentTotal: Number(snapshot.totalAdjustment ?? 0),
      payableTotal: Number(snapshot.proposedPayable ?? 0)
    })
  }
};

const result = JSON.parse(JSON.stringify(
  $vars.persistFinalDisposition.output ?? {}
));

if (result.out_Success !== true) {
  const code = String(
    result.out_ErrorCode ?? "PersistenceError"
  );

  const message = String(
    result.out_ErrorMessage ??
    "Final persistence failed without an error message."
